def forward(groups):
    value = float(groups[0])
    unit = groups[1]
    if unit == 'KB':
        value = int(round(value * 1024))
    else:
        value = int(value)
    return {'stored': [value], 'layout': []}

def inverse(record):
    value = int(record['stored'][0])
    if value >= 1024:
        return f'{value / 1024:.1f} KB'
    else:
        return f'{value} B'
